#include "dome/scene.hpp"
#include "dome/material-bindings.hpp"
#include "persistent-cpp-allocation.hpp"
#include <iostream>
using namespace dome;
#include "refined-role-sampling.hpp"
#include <cmath>
namespace {
size_t checks=0;void check(bool b,const char*m){++checks;std::cout<<(b?"PASS ":"FAIL ")<<m<<std::endl;if(!b)throw std::runtime_error(m);}
bool refuses(auto f,std::string_view wanted){try{f();}catch(const std::exception&e){return std::string_view(e.what()).find(wanted)!=std::string_view::npos;}return false;}
Vec3 original_sample(const std::vector<Vec3> &values,const detail::MirrorSurfacePoint&p){Vec3 v{};for(size_t k=0;k<3;++k)v+=values[p.triangle*3+k]*float(p.barycentric[k]);return v;}
}
int main(int argc,char**argv)try{
 if(argc!=2)return 2;auto scene=Scene::load(argv[1]);const auto exact=scene.encode();const auto &o=scene.active();const auto frames=o.material_bindings->normal_frames;const auto refinement=detail::refine_reflected_key(o.painted->mesh_owner(),detail::KeyMirrorPlane{0},.0001f);double maximum=0,minimum_length=1,normalization_error=0;size_t prefixes=0;
 for(const auto &role:{frames->pbr,frames->mtoon,frames->canonical})if(role){auto sampled=detail::sample_refined_role_field(refinement,role);check(sampled.before==role&&sampled.normals.size()==refinement.corners.size(),"Detached samples keep exact original role owner/IDs separate from derived corners");
  auto roomy=std::make_shared<NormalFrames>(*role);roomy->normals.reserve(role->normals.capacity()+1024);const auto roomy_field=detail::sample_refined_role_field(refinement,roomy);check(roomy_field.working_bytes>sampled.working_bytes+1024*sizeof(Vec3)-sizeof(Vec3),"Genuine unused borrowed source capacity and metadata are charged rather than hidden by logical lengths");detail::KeyMirrorLimits tight;tight.max_bytes=sampled.working_bytes;check(refuses([&]{detail::sample_refined_role_field(refinement,roomy,tight);},"working budget"),"Actual unchanged-valued source with larger resident capacity refuses the original exact working limit");
  for(size_t c=0;c<sampled.normals.size();++c){const auto expected=original_sample(role->normals,refinement.corners[c].current);maximum=std::max(maximum,double(length(expected-sampled.normals[c])));minimum_length=std::min(minimum_length,double(length(expected)));if(!role->tangents.empty()){Vec3 tangent{};const auto &p=refinement.corners[c].current;for(size_t k=0;k<3;++k){const auto t=role->tangents[p.triangle*3+k];tangent+=Vec3{t[0],t[1],t[2]}*float(p.barycentric[k]);}const auto t=sampled.tangents[c];maximum=std::max(maximum,double(length(tangent-Vec3{t[0],t[1],t[2]})));check(t[3]==role->tangents[p.triangle*3][3],"Actual source triangle tangent handedness survives raw interpolation without invented signs");}for(size_t t=0;t<role->targets.size();++t){const auto &a=role->targets[t],&b=sampled.targets[t];check(a.id==b.id&&a.normals.empty()==b.normals.empty()&&a.tangents.empty()==b.tangents.empty(),"Actual artist target identity and absent-field semantics survive refinement");if(!a.normals.empty())maximum=std::max(maximum,double(length(original_sample(a.normals,refinement.corners[c].current)-b.normals[c])));if(!a.tangents.empty())maximum=std::max(maximum,double(length(original_sample(a.tangents,refinement.corners[c].current)-b.tangents[c])));}}
  for(size_t c=0;c<sampled.normals.size();c+=3){Vec3 raw{},wrong{};for(size_t k=0;k<3;++k){raw+=sampled.normals[c+k]/3;wrong+=normalized(sampled.normals[c+k])/3;}normalization_error=std::max(normalization_error,double(length(normalized(raw)-normalized(wrong))));}
  detail::KeyMirrorLimits exact_limits;exact_limits.max_bytes=sampled.working_bytes;exact_limits.max_work=sampled.work_units;check(detail::sample_refined_role_field(refinement,role,exact_limits).normals.size()==sampled.normals.size(),"Exact resident source/provenance/output byte and sample-work limits succeed");auto below=exact_limits;--below.max_bytes;check(refuses([&]{detail::sample_refined_role_field(refinement,role,below);},"working budget"),"One below genuine complete working byte footprint refuses before output allocation");below=exact_limits;--below.max_work;check(refuses([&]{detail::sample_refined_role_field(refinement,role,below);},"work budget"),"One below actual sample-work count refuses before output allocation");
  size_t polls=0;detail::KeyMirrorLimits observed;observed.cancelled=[&]{++polls;return false;};detail::sample_refined_role_field(refinement,role,observed);for(size_t cut=1;cut<=polls;++cut){size_t at=0;auto cancel=observed;cancel.cancelled=[&]{return ++at>=cut;};check(refuses([&]{detail::sample_refined_role_field(refinement,role,cancel);},"cancelled"),"Every actual sampling cancellation publishes no detached field");}
  size_t calls=0;{allocation_probe::Guard guard(SIZE_MAX);detail::sample_refined_role_field(refinement,role);calls=allocation_probe::calls;}for(size_t cut=0;cut<calls;++cut){bool denied=false;{allocation_probe::Guard guard(cut);try{detail::sample_refined_role_field(refinement,role);}catch(const std::bad_alloc&){denied=true;}}check(denied,"Every measured persistent C++ allocation denial cleans detached refined role output");}prefixes+=calls;
  check(detail::sample_refined_role_field(refinement,role).normals.size()==sampled.normals.size(),"Actual allocation/cancel contexts retry without persistent cache or authority");
 }
 std::cout<<"RAW_REFINED_FIELD max="<<maximum<<" minimum_base_length="<<minimum_length<<" normalized_midpoint_direction_error="<<normalization_error<<" allocation_prefixes="<<prefixes<<std::endl;check(maximum<=1e-7&&minimum_length<.999&&normalization_error>1e-6,"Actual artist field proves raw barycentric preservation and sensitivity to normalization at inserted vertices");check(scene.encode()==exact,"Detached role sampling/cap/cancel/OOM preserve complete real canonical/F32 source");std::cout<<"PASS "<<checks<<" detached refined artist-field checks\n";return 0;
}catch(const std::exception&e){allocation_probe::active=false;std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
